import{_ as i,C as s,o as r,c as d,a5 as t,j as a,a as n,E as l}from"./chunks/framework.Bj-lFevX.js";const y=JSON.parse('{"title":"Under the hood","description":"","frontmatter":{},"headers":[],"relativePath":"guide/under-the-hood.md","filePath":"guide/under-the-hood.md"}'),c={name:"guide/under-the-hood.md"},h={id:"the-classic-pipeline",tabindex:"-1"};function p(u,e,m,f,g,_){const o=s("Badge");return r(),d("div",null,[e[3]||(e[3]=t('<h1 id="under-the-hood" tabindex="-1">Under the hood <a class="header-anchor" href="#under-the-hood" aria-label="Permalink to &quot;Under the hood&quot;">​</a></h1><h2 id="processing-flow" tabindex="-1">Processing flow <a class="header-anchor" href="#processing-flow" aria-label="Permalink to &quot;Processing flow&quot;">​</a></h2><p>The <code>Builder</code> runs one of three pipelines, depending on the <a href="/swagger-php/guide/modes.html">mode</a>.</p><p>In spec mode, the Assembler reads the spec attributes into a <code>Specification</code>. The Resolver adds the classes it references, the augmenters enrich it, and a compiler for the target OpenAPI version writes the document. <a href="/swagger-php/reference/architecture.html">Spec pipeline architecture</a> describes each step.</p><p>Hybrid mode scans with the classic <code>Generator</code> and its analyser, then hands the result to the same augmenters and compilers (<a href="/swagger-php/guide/modes.html#hybrid">Hybrid</a>).</p>',5)),a("h2",h,[e[0]||(e[0]=n("The classic pipeline ",-1)),l(o,{type:"warning",text:"deprecated"}),e[1]||(e[1]=n()),e[2]||(e[2]=a("a",{class:"header-anchor",href:"#the-classic-pipeline","aria-label":'Permalink to "The classic pipeline <Badge type="warning" text="deprecated" />"'},"​",-1))]),e[4]||(e[4]=t('<ul><li>The <code>Generator</code> iterates over the given sources (Symfony <code>Finder</code>, file/directory list, etc.)</li><li>The configured analyser (<code>AnalyserInterface</code>) reads the files and builds an <code>Analysis</code> object. The default is the <code>ReflectionAnalyser</code>.</li><li>The <code>Analysis</code> object and its annotation instances are then processed by the configured processors.</li><li>If enabled, the annotation instances are validated.</li><li>The root <code>OpenApi</code> instance then contains all annotation instances and is serialized into YAML/JSON.</li></ul><h3 id="context" tabindex="-1"><code>Context</code> <a class="header-anchor" href="#context" aria-label="Permalink to &quot;`Context`&quot;">​</a></h3><p>Each annotation instance is associated with a unique <code>Context</code> instance. This contains details, collected by the parser/analyser, about the PHP context where the attribute or annotation was found.</p><p>Typically, there will be a processor that uses the data to augment the annotation instance.</p><p><strong>Examples of the data collected:</strong></p><ul><li>class/interface/trait/enum names</li><li>property names</li><li>doctype or native type hints</li><li>file name and line number</li></ul><h3 id="analysis" tabindex="-1">Analysis <a class="header-anchor" href="#analysis" aria-label="Permalink to &quot;Analysis&quot;">​</a></h3><p>Contains all detected annotation instances and other relevant metadata.</p><p>It uses a <code>SplObjectStorage</code> instance to store the annotation instances.</p>',9))])}const T=i(c,[["render",p]]);export{y as __pageData,T as default};
